import { Component, computed, input } from '@angular/core';

/** hrm-date-cell — ô ngày/giờ định dạng (Intl) + dòng phụ tùy chọn (VD "3 ngày trước", do bên gọi cấp).
 *  Nhận Date | chuỗi ISO | timestamp. mode = date | datetime | time. */
@Component({
  selector: 'hrm-date-cell',
  template: `
    <span class="dc-main">{{ main() }}</span>
    @if (sub()) { <span class="dc-sub">{{ sub() }}</span> }
  `,
  host: { class: 'hrm-date-cell' },
  styles: [`
:host { display: inline-flex; flex-direction: column; min-width: 0; }
.dc-main { font-size: var(--fs-14); color: var(--text-strong); line-height: 1.35; font-variant-numeric: tabular-nums;
  white-space: nowrap; }
.dc-sub { font-size: var(--fs-12); color: var(--text-sub); line-height: 1.3; white-space: nowrap; }
  `],
})
export class HrmDateCell {
  readonly value = input<Date | string | number | null>(null);
  readonly mode = input<'date' | 'datetime' | 'time'>('date');
  readonly locale = input('vi-VN');
  /** Dòng phụ (VD tương đối "hôm qua") — bên gọi cấp để tránh phụ thuộc thư viện relative-time. */
  readonly sub = input('');

  protected readonly main = computed(() => {
    const v = this.value();
    if (v == null || v === '') return '';
    const d = v instanceof Date ? v : new Date(v);
    if (isNaN(d.getTime())) return String(v);
    const opts: Intl.DateTimeFormatOptions =
      this.mode() === 'time'
        ? { hour: '2-digit', minute: '2-digit' }
        : this.mode() === 'datetime'
          ? { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }
          : { year: 'numeric', month: '2-digit', day: '2-digit' };
    return new Intl.DateTimeFormat(this.locale(), opts).format(d);
  });
}
